function updateNamePreview(edit=false){const base=E.cleanName($(edit?'editCityName':'cityName').value),type=$(edit?'editCityType':'cityType').value;$(edit?'editNamePreview':'cityNamePreview').textContent=(base||'〇〇')+(TYPE[type]||'市');$(edit?'applyIdentity':'establish').disabled=!base;if(!edit){const c=city();if(c&&!c.founded){c.plannedBase=$('cityName').value;c.plannedType=type;clearTimeout(saveTimer);saveTimer=setTimeout(save,650);}}}
function openIdentity(id=null){identityTarget=Number.isInteger(id)&&region.cities[id]?.founded?id:null;const c=identityTarget===null?null:region.cities[identityTarget];$('identityCurrent').textContent=c?code(c)+' / '+c.name:'地域の名前';$('editRegionName').value=region.name;$('editMunicipality').hidden=!c;$('applyIdentity').disabled=false;if(c){$('editCityName').value=c.baseName??c.name;$('editCityType').value=c.municipalityType||'city';updateNamePreview(true);}$('identityDialog').showModal();}
function refreshSaveDialog(){const active=region.cities.filter(c=>c.founded);$('savedRegionName').textContent=region.name;$('savedSummary').textContent=active.length+'自治体 · '+fmt(active.reduce((v,c)=>v+(c.stats.population||0),0))+'人 · '+(Math.floor(region.month/12)+1)+'年目 '+(region.month%12+1)+'月';$('saveDialogState').textContent=$('saveState').textContent;}
