function formatRegionUpdated(ts){try{return new Date(ts||0).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){return ''}}
async function renderRegionLibrary(){const list=$('regionLibraryList');list.innerHTML='<div class="region-library-empty">地方一覧を読み込んでいます…</div>';try{let records=await getAllRegionMeta();records.sort((a,b)=>(a.id===activeRegionId?-1:b.id===activeRegionId?1:(b.updatedAt||0)-(a.updatedAt||0)));$('regionLibraryCount').textContent=records.length+'地方';if(!records.length){list.innerHTML='<div class="region-library-empty">保存されている地方はまだありません。</div>';return;}list.innerHTML=records.map(r=>{let founded=Number.isFinite(r.foundedCount)?r.foundedCount:0,pop=Number.isFinite(r.population)?r.population:0,month=Number.isFinite(r.month)?r.month:0,current=r.id===activeRegionId;return '<article class="region-library-card '+(current?'current':'')+'"><div class="region-library-main"><div class="region-library-title"><strong>'+esc(r.name||'名称未設定')+'</strong>'+(current?'<span class="region-current-badge">現在</span>':'')+'</div><div class="region-library-meta">'+founded+'自治体 · '+fmt(pop)+'人 · '+(Math.floor(month/12)+1)+'年目 '+(month%12+1)+'月 · '+esc(formatRegionUpdated(r.updatedAt))+'更新</div></div><div class="region-library-actions"><button class="secondary" data-open-region="'+esc(r.id)+'" '+(current?'disabled':'')+'>'+(current?'プレイ中':'開く')+'</button><button class="danger" data-delete-region="'+esc(r.id)+'" '+(current?'disabled':'')+'>削除</button></div></article>';}).join('');}catch(e){$('regionLibraryCount').textContent='利用不可';list.innerHTML='<div class="region-library-empty">地方一覧を読み込めませんでした。現在の地方は従来どおり自動保存されています。<br>'+esc(e.message||'IndexedDBを利用できません')+'</div>';}}
