function updateChecklist(c){let items=[['道路をつなぐ',c.tiles.some(t=>t.road)],['電気を届ける',c.stats.power>0],['住宅と働く場所をつくる',c.tiles.some(t=>t.zone==='res')&&c.tiles.some(t=>t.zone==='com'||t.zone==='ind')]];$('starterChecklist').hidden=(c.stats.population||0)>120;$('starterChecklist').innerHTML=items.map(([name,ok],i)=>'<div class="'+(ok?'done':'')+'"><i>'+(ok?'✓':i+1)+'</i><span>'+name+'</span></div>').join('');}

