function configureView(){const c=city(),terrain=c&&!c.founded;$('regionPanel').hidden=!!c;$('terrainPanel').hidden=!terrain;$('buildPanel').hidden=!c||terrain;$('dashboard').hidden=!c||terrain;$('mobileStats').hidden=!c?.founded;$('backRegion').disabled=!c;$('speeds').style.opacity=c?.founded?'1':'.45';$('layer').disabled=!c;updateIdentityHeader();$('mapSubtitle').textContent=c?(terrain?'A NEW BEGINNING':'EVERYDAY, GROWING'):'A WORLD OF POSSIBILITIES';$('inspector').hidden=true;selection=null;hover=null;preview=[];routePreview=[];elapsed=0;renderer.setup(region,cityId);renderer.fit(camera);$('centerView').textContent='100%';selectTool('inspect');if(terrain){$('cityName').value=c.plannedBase??suggestedNames[c.id];$('cityType').value=Object.hasOwn(TYPE,c.plannedType)?c.plannedType:'city';updateNamePreview();setTerrainStage('name');}document.querySelectorAll('.left').forEach(p=>p.classList.remove('mobile-hidden'));$('dashboard').classList.remove('show');$('mobileStats').setAttribute('aria-expanded','false');$('mobileTools').textContent=c?'道具':'地域';$('mobileTools').setAttribute('aria-expanded','true');renderCategories();renderTools();setLayer(layer);updateUI();}
