function selectTool(k){if(cameraDragMode){cameraDragMode=false;updateCameraUI();}if(k!==selected)rotation=0;let d=D[k],c=city();if(!d)return;if(c&&!c.founded&&!d.terrain&&k!=='inspect')return;selected=k;selection=null;$('inspector').hidden=true;preview=[];routePreview=[];$('world').style.cursor=k==='inspect'?'grab':'crosshair';let footprint=d.w||d.h?' · '+E.buildSize(k,rotation).w+'×'+E.buildSize(k,rotation).h:(!d.zone&&!d.network&&!d.terrain&&!['inspect','bulldoze','dezone','forest'].includes(k)?' · 1×1':'');$('toolTitle').textContent=c?d.name+footprint+(d.price?' · '+cash(d.price):''):'地域を見渡す';$('toolMark').innerHTML=c?symbols[d.cat]:symbols.map;$('toolDescription').textContent=c?d.desc:'区画を選んで土地を開く。隣接する都市をつなぎ、地域全体を育てましょう。';if(k==='pipe'){setLayer('water')}else if(k==='sewerPipe'){setLayer('sewage')}else if(k==='subway'){setLayer('subway')}else if(k==='powerLine'){setLayer('power')}else if(!['inspect','bulldoze'].includes(k)&&['water','sewage','subway','power'].includes(layer)){setLayer('normal')}renderTools();document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===selected)));}
function renderCategories(){let cats=[['zone','区画'],['traffic','交通'],['power','電気'],['water','水道'],['civic','公共'],['environment','環境'],['terrain','地形']];$('categories').innerHTML=cats.map(([k,n])=>'<button data-category="'+k+'" class="'+(category===k?'active':'')+'">'+n+'</button>').join('');}
function toolHTML(k){let d=D[k],c=city(),locked=d.unlock&&(c?.stats?.population||0)<d.unlock;let size=d.w||d.h?E.buildSize(k,rotation).w+'×'+E.buildSize(k,rotation).h:d.network?'線状':d.zone?'区画':d.terrain?'ブラシ':'1×1';return '<button class="tool '+(selected===k?'active':'')+'" data-tool="'+k+'" aria-pressed="'+(selected===k)+'"'+(d.zone?' data-zone="'+d.zone+'"':'')+(locked?' disabled':'')+' title="'+esc(d.desc)+'"><span class="symbol">'+(d.network==='road'?'<i class="road-swatch '+k+'" aria-hidden="true"></i>':symbols[d.cat])+'</span><strong>'+d.name+'</strong><small>'+(locked?'人口 '+fmt(d.unlock)+'人':d.terrain?'設立前は無料':cash(d.price||0)+' · '+size)+'</small></button>'}
function renderTools(){updateRotationUI();if(!city())return;$('terrainTools').innerHTML=['raise','lower','smooth','flatten'].map(toolHTML).join('');$('tools').innerHTML=Object.keys(D).filter(k=>D[k].cat===category).map(toolHTML).join('');$('buildHint').textContent=category==='terrain'?'設立後の造成は1マス §3。建設済みの土地は先に撤去してください。':category==='zone'?'ドラッグで四角く指定。住宅は戸建→低層集合→中高層→高層→超高層の5段階。上位指定でも条件が整うまでは低い段階から育ちます。':category==='traffic'?'境界へ向かう道だけに✓・!を表示。街路は細道、道路は中央破線、大通りは緑の分離帯、高速は濃い舗装と白い側線。':'大きな施設は敷地全体が空いている必要があります。';}
function updateDistrict(){let c=region.cities[selectedCity],land=c.tiles.filter(t=>t.h>0).length,total=E.N*E.N;$('districtSelect').value=String(selectedCity);$('districtInfo').innerHTML=row('状態',c.founded?(TYPE[c.municipalityType]||'市')+' · 設立済み':'未開発')+row('建設できる陸地',Math.round(land/total*100)+'%')+row('人口',fmt(c.stats?.population)+'人')+row('区画の広さ',E.N+' × '+E.N+'（'+fmt(total)+'マス）');$('landMeter').style.width=Math.round(land/total*100)+'%';$('openCity').textContent=c.founded?c.name+'を開く →':'この土地を開く →';$('districtRename').hidden=!c.founded;let active=region.cities.filter(c=>c.founded);$('foundedCount').textContent=active.length+' / '+region.cities.length;$('regionConnections').innerHTML=active.length?active.map(c=>'<button class="region-chip" data-open-city="'+c.id+'"><span>'+esc(c.name)+'</span><strong>'+fmt(c.stats.population)+'人 →</strong></button>').join(''):'<div class="connection-empty">はじめの一歩は、土地選びから。<br>地図や上の一覧から選べます。</div>';renderDistrictGrid();}

function connectionText(point){const kind=point.kind==='road'?'道路':'鉄道';return {connected:'接続済み','local-missing':'こちら側に'+kind+'が必要','neighbor-missing':'隣町側に'+kind+'が必要',height:'標高差が16mを超えています',unfounded:'両側の都市の設立が必要',outside:'地域の外には接続できません'}[point.status];}
let connectionListSignature='';
function updateConnections(){
 const c=city();if(!c)return;const edges=E.transportEdges(region,c.id),signature=JSON.stringify([c.id,edges]);if(signature===connectionListSignature)return;connectionListSignature=signature;
 const count=edges.reduce((n,e)=>n+e.road+e.rail,0);$('connectionTotal').textContent=count+'か所 接続';
 $('connectionList').innerHTML=edges.filter(e=>e.otherId!==null||e.points.length).map(edge=>{
  const available=edge.otherId!==null;
  const list=edge.points.map((point,i)=>'<option value="'+i+'">'+(point.kind==='road'?'道路':'鉄道')+' X'+point.x+' Y'+point.y+' · '+esc(connectionText(point))+'</option>').join('');
  return '<div class="connection-row"><header><strong>'+edge.label+' · '+esc(edge.name)+'</strong><button data-edge-focus="'+edge.key+'">境界へ</button></header><div class="connection-counts"><span>道路 '+edge.road+'か所</span><span>鉄道 '+edge.rail+'か所</span></div>'+(!available?'<p>この先には接続できません。</p>':!edge.founded?'<p>この区画はまだ未開発です。</p>':'')+(list?'<select data-connection-jump="'+edge.key+'" aria-label="'+esc(edge.name)+'との接続地点へ移動"><option value="">接続地点を選ぶ（'+edge.points.length+'件）</option>'+list+'</select>':available&&edge.founded?'<p>境界へ向かう道路・鉄道はありません。</p>':'')+'</div>';
 }).join('');
}
function focusTransport(edge,point=null){
 if(!city())return;const mid=Math.floor(E.N/2),x=point?.x??(edge.dx?(edge.dx>0?E.N-1:0):mid),y=point?.y??(edge.dy?(edge.dy>0?E.N-1:0):mid);
 renderer.setup(region,cityId);camera.zoom=Math.max(camera.zoom,Math.min(1,camera.base*3));const p=renderer.screen(x+.5,y+.5,camera),o=renderer.origin(camera);camera.x+=o.x-camera.x-p.x;camera.y+=o.y-camera.y-p.y;
 $('centerView').textContent=Math.round(camera.zoom/camera.base*100)+'%';hover={x,y};preview=[];
 if(innerWidth<=700){document.querySelectorAll('.left').forEach(p=>p.classList.add('mobile-hidden'));$('mobileTools').setAttribute('aria-expanded','false');$('dashboard').classList.remove('show');$('mobileStats').setAttribute('aria-expanded','false');}
 if(point){inspect({x,y},false);if(innerWidth<=700)$('inspector').hidden=true;toast((point.kind==='road'?'道路':'鉄道')+' · X '+x+' / Y '+y+' · '+connectionText(point));}
}
function connectionInspector(c,t){
 if(t.x!==0&&t.x!==E.N-1&&t.y!==0&&t.y!==E.N-1)return '';
 return E.transportEdges(region,c.id).filter(e=>e.points.some(p=>p.x===t.x&&p.y===t.y)).map(edge=>'<section class="connection-inspect"><strong>'+edge.label+' · '+esc(edge.name)+'との境界</strong>'+edge.points.filter(p=>p.x===t.x&&p.y===t.y).map(p=>'<p>'+(p.kind==='road'?'○ 道路':'◇ 鉄道')+'：'+esc(connectionText(p))+'</p>').join('')+(edge.otherId!==null?'<button data-open-city="'+edge.otherId+'">隣町を開く →</button>':'')+'</section>').join('');
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-edge-focus]');if(!button||!city())return;const edge=E.transportEdges(region,cityId).find(a=>a.key===button.dataset.edgeFocus);if(edge)focusTransport(edge,edge.points.find(p=>p.status==='local-missing')||edge.points[0]);});
document.addEventListener('change',e=>{const select=e.target.closest('[data-connection-jump]');if(!select||select.value===''||!city())return;const edge=E.transportEdges(region,cityId).find(a=>a.key===select.dataset.connectionJump),point=edge?.points[+select.value];if(point)focusTransport(edge,point);select.value='';});

