 if(t.zone==='res'){const dest=t.commuteDestCity!=null?region.cities[t.commuteDestCity]?.name||'勤務先':'—';content+='<div class="inspect-section"><h3>暮らし・通勤</h3>'+row('所得層',['—','低所得 R$','中所得 R$$','高所得 R$$$'][t.wealth||1])+row('教育 / 医療',fmt(t.education)+' / '+fmt(t.health))+row('就業率',fmt((t.employment||0)*100)+'%',(t.employment||0)<.35)+row('平均通勤時間',t.commuteTime?fmt(t.commuteTime)+'分':'—',t.commuteTime>55)+row('主な交通手段',t.commuteMode||'—')+row('主な勤務先',dest)+'</div>'+(t._route?.length?'<div class="inspect-actions"><button class="secondary" data-route="commute">通勤経路を見る</button><button class="secondary" data-layer-jump="traffic">交通量を見る</button></div>':'');}
