function path(a,b,rect){let out=[];if(rect){for(let y=Math.min(a.y,b.y);y<=Math.max(a.y,b.y);y++)for(let x=Math.min(a.x,b.x);x<=Math.max(a.x,b.x);x++)out.push({x,y});}else{let x=a.x,y=a.y;out.push({x,y});while(x!==b.x){x+=Math.sign(b.x-x);out.push({x,y})}while(y!==b.y){y+=Math.sign(b.y-y);out.push({x,y})}}return out;}
