function drawStatsChart(){const c=city();if(!c)return;const canvas=$('statsChart'),ctx=canvas.getContext('2d'),metric=$('statsMetric').value,data=(c.historyData||[]).slice(-120),vals=data.map(x=>Number(x[metric])||0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#fbfcf6';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#d8e1d2';ctx.lineWidth=1;for(let i=1;i<5;i++){let y=i*canvas.height/5;ctx.beginPath();ctx.moveTo(36,y);ctx.lineTo(canvas.width-8,y);ctx.stroke();}if(!vals.length){ctx.fillStyle='#7b8a74';ctx.font='13px sans-serif';ctx.fillText('時間が進むと統計が記録されます。',45,canvas.height/2);return;}let min=Math.min(...vals),max=Math.max(...vals);if(metric==='unemployment'){min=0;max=Math.max(.1,max);}if(max===min)max=min+1;const x0=38,y0=canvas.height-24,w=canvas.width-x0-10,h=canvas.height-40;ctx.strokeStyle='#426f62';ctx.lineWidth=3;ctx.beginPath();vals.forEach((v,i)=>{const x=x0+(vals.length===1?0:i/(vals.length-1))*w,y=y0-(v-min)/(max-min)*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#667c6d';ctx.font='10px sans-serif';ctx.fillText(metric==='unemployment'?Math.round(max*100)+'%':fmt(max),3,16);ctx.fillText(metric==='unemployment'?Math.round(min*100)+'%':fmt(min),3,y0);ctx.fillText(data.length+'か月',canvas.width-52,canvas.height-7);}
