function updateUtilityUI(){
 const c=city(),ready=!!c?.founded;for(const kind of ['power','water','sewage']){const b=$(kind+'View');b.disabled=!ready;b.setAttribute('aria-pressed',String(layer===kind));b.classList.toggle('active',layer===kind);}
 $('utilitySummary').hidden=!ready;if(!ready)return;
 const zones=c.tiles.filter(t=>t.zone),powerMissing=zones.filter(t=>!t.powered).length,waterMissing=zones.filter(t=>!t.watered).length,facilitiesMissing=c.facilities.filter(f=>!f.powered).length;
 $('powerSummary').textContent=zones.length?'区画 '+(zones.length-powerMissing)+' / '+zones.length+'マスに通電':'区画はまだありません';
 $('sewageSummary').textContent=fmt(c.stats.sewageUse||0)+' / '+fmt(c.stats.sewageCapacity||0)+' 単位 / 月';$('sewageIssue').textContent=c.stats.sewageUntreated>1?'未処理：'+fmt(c.stats.sewageUntreated)+' 単位 / 月':'未処理の下水なし';$('sewageIssue').classList.toggle('bad',c.stats.sewageUntreated>1);
 $('waterSummary').textContent=zones.length?'区画 '+(zones.length-waterMissing)+' / '+zones.length+'マスに給水':'区画はまだありません';
 $('powerIssue').textContent=powerMissing||facilitiesMissing?'未通電：区画 '+powerMissing+'マス・施設 '+facilitiesMissing+'か所':'電気の未供給なし';
 $('waterIssue').textContent=waterMissing?'未給水：区画 '+waterMissing+'マス':'水道の未供給なし';
 $('powerIssue').classList.toggle('bad',!!(powerMissing||facilitiesMissing));$('waterIssue').classList.toggle('bad',!!waterMissing);
}
function utilityLegend(kind){
 if(kind==='sewage'){const s=city()?.stats||{};return '<strong class="utility-legend-title">下水の集め方</strong><div class="utility-legend-grid">'+[['on','✓ 処理中・処理可能'],['shortage','! 処理能力不足'],['off','× 処理施設に未接続'],['unconnected','下水管の範囲外']].map(([state,label])=>'<span><i class="utility-swatch sewage '+state+'"></i>'+label+'</span>').join('')+'</div><p>発生 '+fmt(s.sewageUse)+' / 処理能力 '+fmt(s.sewageCapacity)+'、未処理 '+fmt(s.sewageUntreated)+' 単位 / 月。</p><p>下水管から4マス以内に届きます。処理施設には道路と電気が必要です。排水口は稼働時に水を汚します。</p>';}
 const c=city(),water=kind==='water',zones=c?.tiles.filter(t=>t.zone)||[],missing=zones.filter(t=>water?!t.watered:!t.powered).length;
 const rows=[['on',water?'✓ 給水中・給水可能':'✓ 通電中・接続可能'],['shortage','! '+(water?'水量不足':'電力不足')],['off','× '+(water?'水源から未供給':'電源から未供給')],['unconnected',water?'給水範囲外':'送電網の範囲外']];
 return '<strong class="utility-legend-title">'+(water?'水道の届き方':'電気の届き方')+'</strong><div class="utility-legend-grid">'+rows.map(([state,text])=>'<span><i class="utility-swatch '+kind+' '+state+'"></i>'+text+'</span>').join('')+'</div><p>'+missing+' / '+zones.length+'区画マスが未供給。斜線は未供給の区画・設備です。</p><p>'+(water?'水道管から4マス以内を表示。赤い管は水が来ていません。':'黄色は現在通電中、または既存の送電網から2マス以内で新しい区画・施設を接続できる範囲です。')+' 土地を「調べる」と原因が分かります。</p>';
}
