function serviceLegend(kind){if(kind==='service')return '<strong class="utility-legend-title">公共施設の効果範囲</strong><div class="gradient service-gradient"></div><div class="scale"><span>効果なし</span><span>効果が強い</span></div><p>医療・教育・警察・消防・公園のうち、そのマスで最も強い公共サービス効果を総合表示しています。</p><p>個別の範囲は右のデータマップから選ぶか、施設を「調べる」と確認できます。</p>';const c=city(),f=selection&&c?E.facility(c,E.tile(c,selection.x,selection.y)):null,info=f&&D[f.type].service===kind?E.serviceInfo(c,f):null;return '<strong class="utility-legend-title">'+SERVICE_NAMES[kind]+'の効果範囲</strong><div class="gradient service-gradient"></div><div class="scale"><span>効果なし</span><span>効果が強い</span></div>'+(info?'<p><strong>'+esc(D[f.type].name)+'</strong> · '+(info.active?'半径 '+(Math.round(info.radius*10)/10)+'マス · 予算 '+info.funding+'%':'停止中：'+esc(info.reason))+'</p><p>選択した施設の実際の効果を表示しています。</p>':'<p>稼働中の施設の効果を合計して表示しています。施設を「調べる」と、その施設だけの範囲を確認できます。</p>')+'<p>範囲内でも、施設から離れるほど効果は弱まります。距離の単位はゲーム内のマスです。</p>';}
