 $('cameraToggle').onclick=()=>toggleCameraPanel($('cameraPanel').hidden);
 $('cameraClose').onclick=()=>toggleCameraPanel(false);
 $('cameraLeft').onclick=()=>changeCamera(camera.angle-15);
