function applyGameCommand(cmd,actor={id:'host'}){
 try{
  if(!cmd||typeof cmd!=='object'||Array.isArray(cmd))return {ok:false,error:'操作が不正です。'};
  const isInt=(n,a,b)=>Number.isInteger(n)&&n>=a&&n<=b,num=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;
  const needsCity=['build','sculpt','establish','regenerate','tax','funding','policy','localFunding','historical','disaster'];
  if(needsCity.includes(cmd.op)&&!isInt(cmd.cityId,0,E.R*E.R-1))return {ok:false,error:'自治体を選んでください。'};
  const c=region.cities[cmd.cityId],beforeFounded=!!city()?.founded;let r={ok:false,error:'この操作は実行できません。'};
  switch(cmd.op){
   case 'build':{
    if(!c.founded||!Object.hasOwn(D,cmd.kind)||D[cmd.kind].terrain||cmd.kind==='inspect'||!Array.isArray(cmd.points)||!cmd.points.length||cmd.points.length>E.N*E.N||cmd.points.some(p=>!p||!isInt(p.x,0,E.N-1)||!isInt(p.y,0,E.N-1))||!['normal','power','water','subway','air','pollution','traffic','desirability','landValue','crimeRisk','fireRisk','service','health','education','police','fire','park'].includes(cmd.layer))break;
    if(!isInt(cmd.rotation??0,0,1)||!(cmd.autoStreets==null||typeof cmd.autoStreets==='boolean'))break;r=E.build(region,cmd.cityId,cmd.points,cmd.kind,cmd.layer,cmd.rotation??0,cmd.autoStreets!==false);break;
   }
   case 'sculpt':{if(!['raise','lower','smooth','flatten'].includes(cmd.kind)||!isInt(cmd.x,0,E.N-1)||!isInt(cmd.y,0,E.N-1)||!isInt(cmd.radius,0,5)||(cmd.target!=null&&!num(cmd.target,-25,100)))break;r=E.sculpt(region,cmd.cityId,cmd.x,cmd.y,cmd.kind,cmd.radius,cmd.target??null);break;}
   case 'establish':{if(c.founded||!Object.hasOwn(TYPE,cmd.type)||!['easy','normal','hard'].includes(cmd.difficulty)||typeof cmd.base!=='string'||!E.cleanName(cmd.base))break;r=E.establish(region,cmd.cityId,E.cleanName(cmd.base)+TYPE[cmd.type],cmd.difficulty,cmd.type);break;}
   case 'regenerate':{if(c.founded||!['plain','coast','river','mountains'].includes(cmd.preset)||!num(cmd.rough,0,90))break;r=E.regenerateCity(region,cmd.cityId,cmd.preset,cmd.rough);break;}
   case 'tax':{if(!c.founded||!['res','com','ind'].includes(cmd.key)||!num(cmd.value,0,20))break;c.tax[cmd.key]=cmd.value;region.revision++;r={ok:true};break;}
   case 'funding':{if(!c.founded||!['education','health','safety','transport'].includes(cmd.key)||!num(cmd.value,20,120))break;c.funding[cmd.key]=cmd.value;region.revision++;r={ok:true};break;}
   case 'policy':{if(!c.founded||!Object.hasOwn(E.POLICY_INFO,cmd.key)||typeof cmd.value!=='boolean')break;c.ordinances[cmd.key]=cmd.value;region.revision++;r={ok:true};break;}
   case 'localFunding':{if(!c.founded||!Number.isSafeInteger(cmd.id)||!num(cmd.value,20,120))break;const f=c.facilities.find(f=>f.id===cmd.id);if(!f)break;f.localFunding=cmd.value;region.revision++;r={ok:true};break;}
   case 'historical':{if(!c.founded||!isInt(cmd.x,0,E.N-1)||!isInt(cmd.y,0,E.N-1)||typeof cmd.value!=='boolean')break;let t=E.lotRoot(c,E.tile(c,cmd.x,cmd.y));if(!t?.zone||!t.level)break;t.historical=cmd.value;region.revision++;r={ok:true};break;}
   case 'disaster':{if(!c.founded||!['quake'].includes(cmd.kind)||!isInt(cmd.severity,1,3))break;r=E.triggerDisaster(region,cmd.cityId,cmd.kind,cmd.severity);break;}
   case 'trade':{if(!isInt(cmd.seller,0,E.R*E.R-1)||!isInt(cmd.buyer,0,E.R*E.R-1)||cmd.seller===cmd.buyer||!region.cities[cmd.seller].founded||!region.cities[cmd.buyer].founded||!['power','water','garbage'].includes(cmd.resource)||!isInt(cmd.amount,1,10000))break;r=E.contract(region,cmd.seller,cmd.buyer,cmd.resource,cmd.amount);break;}
   case 'cancelTrade':{if(!Number.isSafeInteger(cmd.id)||!region.contracts.some(d=>d.id===cmd.id))break;region.contracts=region.contracts.filter(d=>d.id!==cmd.id);region.revision++;r={ok:true};break;}
   case 'identity':{
    if(typeof cmd.regionName!=='string'||!E.cleanName(cmd.regionName,24))break;
    if(cmd.cityId!==null){if(!isInt(cmd.cityId,0,E.R*E.R-1)||typeof cmd.base!=='string'||!E.cleanName(cmd.base)||!Object.hasOwn(TYPE,cmd.type))break;r=E.renameMunicipality(region,cmd.cityId,cmd.base,cmd.type);if(!r.ok)break;}
    region.name=E.cleanName(cmd.regionName,24);region.revision++;r={ok:true};break;
   }
   case 'speed':{if(actor.id!=='host'||![0,1,3,10,30].includes(cmd.value))break;speed=cmd.value;elapsed=0;r={ok:true};break;}
  }
  if(r.ok){E.analyze(region);if(city()&&!beforeFounded&&city().founded){configureView();category='traffic';renderCategories();selectTool('road');}else{updateIdentityHeader();updateUI();renderTools();}queueGameSave();room?.markDirty(true);}
  return r;
 }catch(e){return {ok:false,error:'操作を実行できませんでした。地図を確認してやり直してください。'};}
}
function requestGameCommand(cmd){
 if(room?.isGuest())return room.command(cmd);
 return applyGameCommand(cmd,{id:'host'});
}
async function act(cmd,{silent=false}={}){const result=await requestGameCommand(cmd);if(!result.ok){if(!silent||Date.now()-lastBrushError>1800){lastBrushError=Date.now();toast(result.error,true);}}else{if(result.notice&&Date.now()-lastBrushError>2500){lastBrushError=Date.now();toast(result.notice,true);}if(!silent)beep();}return result;}
function receiveSharedState(packed){
 if(!packed||typeof packed!=='object'||!Array.isArray(packed.cities)||!packed.compact)throw Error('地域データが不正です');
 const wasFound=!!city()?.founded,first=!receivedSharedState,next=E.restore(JSON.stringify(packed));delete next.onlineRoom;
 speed=[0,1,3,10,30].includes(next.clockSpeed)?next.clockSpeed:0;delete next.clockSpeed;region=next;receivedSharedState=true;
 if(!region.cities[cityId])cityId=null;if(!region.cities[selectedCity])selectedCity=0;
 if(first||wasFound!==!!city()?.founded)configureView();else{updateIdentityHeader();updateUI();renderTools();}
 if(city()?.founded&&$('budgetDialog').open){for(const input of document.querySelectorAll('[data-tax],[data-funding]')){const key=input.dataset.tax||input.dataset.funding,value=input.dataset.tax?city().tax[key]:city().funding[key];if(document.activeElement!==input)input.value=value;const label=$(input.dataset.tax?'taxVal-'+key:'fundVal-'+key);if(label)label.textContent=value+'%';}}
 queueGameSave();
}
function hostClock(dt){
 if(room?.role!=='host'||!speed||!region.cities.some(c=>c.founded))return;
 elapsed+=dt*speed;if(elapsed>=10){elapsed-=10;const start=performance.now();E.tick(region);room.metrics.applyMs=performance.now()-start;updateUI();renderTools();queueGameSave();room.markDirty();}
}
function roomEvent(event){
 if(event.type==='left'){
  $('chatPanel').hidden=true;chatUnread=0;renderedChatIds.clear();$('chatMessages').replaceChildren();
  if(event.previousRole==='guest'&&personalSession){region=E.restore(personalSession.data);cityId=personalSession.cityId;selectedCity=personalSession.selectedCity;personalSession=null;receivedSharedState=false;speed=0;configureView();}
  if(event.previousRole==='host'){speed=0;updateUI();save();}
  $('joinPassword').value='';$('roomPassword').value='';$('roomCode').value='';prepareRoomSetup();
 }
 if(event.type==='chat'){renderChat();if($('chatPanel').hidden&&room?.active()){chatUnread++;$('chatUnread').hidden=false;$('chatUnread').textContent=chatUnread>99?'99+':chatUnread;}}
 if(event.type==='typing')renderTyping();
 if(event.type==='notice'){roomMessage(event.message,true);}
 if(event.type==='disconnected'){speed=0;roomMessage(event.message,true);toast('接続が切れました。共同プレイは停止しています。',true);updateUI();}
 renderRoom();
}
function initMultiplayer(){
 room=new MachiRoom({getState:publicRoomState,onCommand:applyGameCommand,onState:receiveSharedState,onTick:hostClock,onRecord:record=>{region.onlineRoom=record;queueGameSave();},onEvent:roomEvent});
 const savedName=offlineStore.getItem(SAVE+'-player-name');if(savedName)$('playerName').value=savedName;
 $('roomButton').onclick=()=>{prepareRoomSetup();renderRoom();$('roomDialog').showModal();};
 $('hostTab').onclick=()=>switchRoomTab('host');$('guestTab').onclick=()=>switchRoomTab('guest');
 $('resumeRoom').onchange=()=>{$('passwordSetup').hidden=$('resumeRoom').checked&&!$('resumeRoomLabel').hidden;};
 $('startHost').onclick=async()=>{
  if(room.active())return;roomMessage('ルームを準備しています…');$('startHost').disabled=true;
  try{if(!save())toast('ブラウザへの保存が使えません。終了前にセーブを書き出してください。',true);await room.host({name:$('roomName').value,userName:$('playerName').value,password:$('roomPassword').value,previous:region.onlineRoom||null,reuse:!$('resumeRoomLabel').hidden&&$('resumeRoom').checked,iceMode:'stun'});$('roomPassword').value='';offlineStore.setItem(SAVE+'-player-name',$('playerName').value);save();roomMessage('ルームを開きました。8文字のコードを友達に送ってください。同じコードで全員が参加できます。');updateUI();}
  catch(e){roomMessage(e.message,true);}finally{$('startHost').disabled=false;renderRoom();}
 };
 $('retryBroker').onclick=()=>room.retryBroker();
 $('joinRoom').onclick=async()=>{
  if(room.active())return;$('joinRoom').disabled=true;roomMessage('コードのルームに接続しています…');
  try{const code=MachiRoom.codes.normalizeCode($('joinCode').value);$('joinCode').value=code;save();personalSession={data:E.serialize(region),cityId,selectedCity};receivedSharedState=false;await room.join({code,userName:$('playerName').value,password:$('joinPassword').value});offlineStore.setItem(SAVE+'-player-name',$('playerName').value);roomMessage('ルームに接続しています。認証と地域の同期が完了するまでお待ちください。');}
  catch(e){if(!room.active())personalSession=null;roomMessage(e.message,true);}finally{$('joinRoom').disabled=false;renderRoom();updateUI();}
 };
 $('acceptParticipants').onchange=()=>room.setAccepting($('acceptParticipants').checked);
 $('leaveRoom').onclick=()=>{if(room.role==='host'&&!window.confirm('地域を保存してルームを終了しますか？参加者全員の共同プレイが停止します。'))return;save();room.leave();roomMessage('ルームを終了しました。');};
 $('exportRoomSave').onclick=()=>$('exportSave').click();
 $('chatToggle').onclick=()=>{$('chatPanel').hidden?openRoomChat():closeRoomChat();};
 $('openChatFromRoom').onclick=()=>{$('roomDialog').close();openRoomChat();};$('closeChat').onclick=closeRoomChat;
 $('chatForm').onsubmit=e=>{e.preventDefault();if(!$('chatInput').value.trim())return;try{room.sendChat($('chatInput').value);$('chatInput').value='';clearTimeout(typingTimer);$('chatInput').focus();}catch(error){toast(error.message,true);}};
 $('chatInput').oninput=()=>{room.sendTyping(!!$('chatInput').value.trim());clearTimeout(typingTimer);typingTimer=setTimeout(()=>room.sendTyping(false),2500);};
 $('chatInput').addEventListener('blur',()=>room.sendTyping(false));
 $('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();$('chatForm').requestSubmit();}});
 document.addEventListener('click',async e=>{const copy=e.target.closest('[data-copy]'),kick=e.target.closest('[data-kick]');if(copy){const area=$(copy.dataset.copy);try{await navigator.clipboard.writeText(area.value);roomMessage('8文字のルームコードをコピーしました。友達に送ってください。');}catch(error){area.focus();area.select();roomMessage('文字列を選択しました。Ctrl+C またはコピー操作で取得してください。');}}if(kick)room.kick(kick.dataset.kick);});
 window.addEventListener('pagehide',()=>{save();room.leave();});
 renderRoom();
}
function switchRoomTab(which){$('hostSetup').hidden=which!=='host';$('guestSetup').hidden=which!=='guest';for(const id of ['host','guest']){$(id+'Tab').classList.toggle('active',which===id);$(id+'Tab').setAttribute('aria-pressed',String(which===id));}}
function prepareRoomSetup(){if(room?.active())return;const record=region.onlineRoom;$('roomName').value=record?.name||region.name+'のルーム';$('resumeRoomLabel').hidden=!record;$('resumeRoom').checked=!!record;$('passwordSetup').hidden=!!record;$('roomPassword').value='';if(record?.hostName&&!$('playerName').value)$('playerName').value=record.hostName;}
function renderRoom(){
 if(!room)return;const v=room.view(),active=room.active();$('roomIdle').hidden=active;$('roomActive').hidden=!active;$('roomButton').classList.toggle('active',active);$('roomButton').classList.toggle('alert',!!v.warning);$('chatToggle').hidden=!active;
 $('roomStatusLine').textContent=active?(v.role==='host'?'ホスト':'参加者')+' · '+v.roomName+' · '+v.members.length+'人'+(v.status==='disconnected'?' · 接続終了':''):'8文字コードで共同プレイ · 低遅延版';
 for(const id of ['openRegionLibrary','newRegionButton','createRegion','restoreBackup','importSaveButton','regionLibraryNew'])$(id).disabled=active;
 document.querySelectorAll('[data-speed]').forEach(b=>{b.disabled=room.isGuest();b.title=room.isGuest()?'時間の進行はホストが操作します':'';});
 if(!active){$('chatUnread').hidden=true;return;}
 $('activeRoomName').textContent=v.roomName;$('participantCount').textContent=(v.members.length||1)+'人';
 const names={opening:'ルームコードを発行中',connecting:'ルームに接続しています',connected:'接続中',syncing:'地域を同期しています',interrupted:'接続が途切れています',disconnected:'接続終了 · 共同プレイは停止中'};
 $('roomConnectionState').textContent=(v.role==='host'?'ホスト · ':'参加者 · ')+(names[v.status]||v.status)+(v.hasPassword?' · パスワードあり':'');
 $('roomWarning').hidden=!v.warning;$('roomWarning').textContent=v.warning;$('hostControls').hidden=v.role!=='host';$('guestControls').hidden=v.role!=='guest';$('acceptParticipants').checked=v.accepting;$('roomCode').value=v.roomCode||'';$('copyRoomCode').disabled=!v.roomCode||!v.brokerOnline||!v.accepting;$('retryBroker').hidden=v.brokerOnline||!room.broker;$('roomCodeHint').textContent=!v.roomCode?'コードを発行しています…':!v.accepting?'参加の受け付けを停止中です。再開すると同じコードで参加できます。':!v.brokerOnline?'接続仲介サービスに再接続するまで新しい参加者は入れません。':'この8文字を友達に送ってください。同じコードで複数人が参加できます。';
 $('leaveRoom').textContent=v.role==='host'?'保存してルームを終了':'退出して自分の地域に戻る';$('openChatFromRoom').disabled=!room.connected();$('chatInput').disabled=$('sendChat').disabled=!room.connected();
 if(v.role==='guest'){$('guestStatusText').textContent=v.status==='connected'?'同期済みです。地図を開き、フレンドと同じ地域で建設できます。時間の進行はホストが操作します。':v.status==='disconnected'?'接続は終了しました。受信済みの地域は書き出せます。再接続する場合は一度退出し、ホストが現在表示している8文字コードを入力してください。':'ホストの地域に接続しています。この画面を開いたまま待ってください。';if(v.status==='connected'){$('joinPassword').value='';}}
 const memberSignature=JSON.stringify(v.members);if(memberSignature!==lastMemberSignature){lastMemberSignature=memberSignature;$('roomMembers').replaceChildren();for(const member of v.members){const row=document.createElement('div');row.className='member-row';const avatar=document.createElement('span');avatar.className='member-avatar';avatar.textContent=Array.from(member.name)[0]||'人';const info=document.createElement('div'),name=document.createElement('strong'),status=document.createElement('small');name.textContent=member.name+(member.id===v.selfId?'（あなた）':'');status.textContent=member.host?'ホスト':(member.lagging?'同期待ち':names[member.status]||'接続中')+(member.rtt==null?'':' · '+Math.round(member.rtt)+'ms');info.append(name,status);row.append(avatar,info);if(v.role==='host'&&!member.host){const kick=document.createElement('button');kick.textContent='接続を終了';kick.dataset.kick=member.id;row.append(kick);}$('roomMembers').append(row);}}
 const inviteSignature=JSON.stringify(v.invites);if(inviteSignature!==lastInviteSignature){lastInviteSignature=inviteSignature;$('pendingInvites').replaceChildren();for(const p of v.invites){const row=document.createElement('div');row.className='pending-row';const info=document.createElement('div'),title=document.createElement('strong'),status=document.createElement('small');title.textContent=p.label||'参加待ち';status.textContent=({preparing:'招待を作成中',invited:'返信待ち',connecting:'接続中',authenticating:'認証中'})[p.status]||'待機中';const cancel=document.createElement('button');cancel.textContent='取消';cancel.dataset.kick=p.id;info.append(title,status);row.append(info,cancel);$('pendingInvites').append(row);}}
 renderTyping();
}
function renderChat(){
 if(!room)return;const log=$('chatMessages'),atBottom=log.scrollHeight-log.scrollTop-log.clientHeight<80;
 if(!room.chat.length&&!renderedChatIds.size){log.replaceChildren();const p=document.createElement('div');p.className='chat-empty';p.textContent='まちづくりの相談を、ここで。';log.append(p);return;}
 if(room.chat.length&&!renderedChatIds.size)log.replaceChildren();
 for(const entry of room.chat){if(renderedChatIds.has(entry.id))continue;renderedChatIds.add(entry.id);const row=document.createElement('div');row.dataset.messageId=entry.id;if(entry.system){row.className='chat-system';row.textContent=entry.text;}else{row.className='chat-message'+(entry.by===room.selfId?' mine':'');const avatar=document.createElement('span');avatar.className='member-avatar';avatar.textContent=Array.from(entry.name)[0]||'人';const body=document.createElement('div');body.className='chat-message-body';const meta=document.createElement('div');meta.className='chat-message-meta';const name=document.createElement('strong'),time=document.createElement('time'),text=document.createElement('div');name.textContent=entry.name;time.textContent=new Date(entry.at).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});text.className='chat-message-text';text.textContent=entry.text;meta.append(name,time);body.append(meta,text);row.append(avatar,body);}log.append(row);}
 const keep=new Set(room.chat.map(x=>x.id));for(const el of [...log.children])if(el.dataset.messageId&&!keep.has(el.dataset.messageId)){renderedChatIds.delete(el.dataset.messageId);el.remove();}if(atBottom)log.scrollTop=log.scrollHeight;
}
function renderTyping(){if(!room)return;const names=room.view().typing.map(x=>x.name);$('typingIndicator').textContent=names.length?names.slice(0,3).join('、')+(names.length>3?' ほか'+(names.length-3)+'人':'')+' が入力中…':'';}
function openRoomChat(){if(!room.active())return;$('chatPanel').hidden=false;$('chatHeading').textContent=room.record?.name||'ルームチャット';chatUnread=0;$('chatUnread').hidden=true;renderChat();$('chatMessages').scrollTop=$('chatMessages').scrollHeight;if(room.connected())$('chatInput').focus();}
function closeRoomChat(){$('chatPanel').hidden=true;room?.sendTyping(false);}

 if(document.modelContext?.registerTool){const register=(name,description,inputSchema,execute)=>{try{document.modelContext.registerTool({name,description,inputSchema,execute:async args=>({content:[{type:'text',text:JSON.stringify(await execute(args))}]})})}catch(e){}};register('read_region','Read region, cities, pollution and trade status.',{type:'object',properties:{}},()=>API.read());register('open_city','Open a city district by its id.',{type:'object',properties:{city_id:{type:'integer',minimum:0,maximum:E.R*E.R-1}},required:['city_id']},a=>API.open(a.city_id));register('build_city_tiles','Build infrastructure or zone land in the currently open established city.',{type:'object',properties:{kind:{type:'string',enum:Object.keys(D).filter(k=>!D[k].terrain&&k!=='inspect')},autoStreets:{type:'boolean'},tiles:{type:'array',maxItems:E.N*E.N,items:{type:'object',properties:{x:{type:'integer',minimum:0,maximum:E.N-1},y:{type:'integer',minimum:0,maximum:E.N-1}},required:['x','y']}}},required:['kind','tiles']},a=>API.build(a));register('start_city','Establish the currently open unincorporated city.',{type:'object',properties:{name:{type:'string'},difficulty:{type:'string',enum:['easy','normal','hard']}},required:['name']},a=>API.establish(a.name,a.difficulty));register('create_neighbor_deal','Create a power, water or garbage-processing deal between connected adjacent cities.',{type:'object',properties:{seller:{type:'integer'},buyer:{type:'integer'},resource:{type:'string',enum:['power','water','garbage']},amount:{type:'integer',minimum:1,maximum:10000}},required:['seller','buyer','resource','amount']},a=>API.trade(a));register('set_city_speed','Pause or set the shared regional simulation speed.',{type:'object',properties:{speed:{type:'integer',enum:[0,1,3,10,30]}},required:['speed']},a=>API.speed(a.speed));}
 // Exposed for deterministic offline validation; the interactive API above stays narrow.
 window.__cityDebug={get room(){return room},applyGameCommand,receiveSharedState,get region(){return region},renderer,camera,frame,openCity,selectTool,setLayer,get cityId(){return cityId}};

